   backend.project.media.source_path='D:/原始视频/素材 speech.wav';await page.reload();await action(page,'resume').click();await stage(page,'review');await action(page,'copy-path').click();assert.equal(await page.evaluate(()=>window.copiedPaths.at(-1)),backend.project.media.source_path);assert.equal(await page.locator('.scene-media-details,.scene-media-path').count(),0);
   await page.evaluate(()=>window.rejectCopy=true);await action(page,'copy-path').click();await page.locator('#toast').filter({hasText:'复制失败'}).waitFor();assert.equal(await page.evaluate(()=>window.copiedPaths.length),1);
