   assert.equal(await page.locator('.scene-stage').evaluate(el=>el.getBoundingClientRect().top),areaTop,'Starting a job must not move the operation area');
   const job=backend.jobs.get('job-1');backend.progressMessage='正在翻译字幕 157 / 271…';job.progress=.58;const reads=backend.jobReads;await eventually(()=>backend.jobReads>reads);
   const checkRow=async()=>{const boxes=await page.locator('.scene-stage').evaluate(el=>{const rect=n=>{const r=n.getBoundingClientRect();return {x:r.x,y:r.y,right:r.right,bottom:r.bottom,height:r.height};};return {card:rect(el),status:rect(el.lastElementChild),bar:rect(el.querySelector('.scene-progress')),stop:rect(el.querySelector('[data-scene-action="stop"]')),progress:rect(el.querySelector('progress')),message:rect(el.querySelector('[data-scene-job-message]'))};});assert.ok(boxes.bar.height<=60);assert.ok(boxes.bar.y>=boxes.status.y);assert.ok(boxes.bar.bottom<boxes.card.bottom);assert.ok(boxes.stop.x>=boxes.progress.right);assert.ok(Math.abs(boxes.stop.right-boxes.status.right)<1,'Stop must align with the stage content right edge');assert.ok(Math.abs((boxes.stop.y+boxes.stop.height/2)-(boxes.bar.y+boxes.bar.height/2))<2,'Stop must stay on the right');assert.ok(boxes.message.bottom<=boxes.status.y,'Progress text belongs to the content label, above the bottom strip');assert.equal(await page.locator('.scene-progress > :not(progress):not(button)').count(),0);assert.ok(await page.locator('[data-scene-job-message]').evaluate(el=>el.scrollWidth<=el.clientWidth&&getComputedStyle(el).textOverflow!=='ellipsis'),'Stage text must be shown in full without ellipsis');assert.equal(await page.locator('.scene-toolbar [data-scene-progress]').count(),0);assert.equal(await page.locator('.scene-stage > [data-scene-progress]').count(),1);assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));return boxes;};
   const setStatus=async(stage,message,expected)=>{job.stage=stage;backend.progressMessage=message;await page.waitForFunction(text=>document.querySelector('[data-scene-job-message]')?.textContent===text,expected);return checkRow();};
   const stableStatus=async()=>{
     const before=await setStatus('extract','正在提取音轨…','提取音轨'),top=await page.locator('.scene-stage').evaluate(el=>el.getBoundingClientRect().top);
     for(const args of [['separate','正在准备人声与背景音乐分离…','加载分离模型'],['separate','正在分离人声与背景音乐 99999 / 99999…','分离人声 99999/99999'],['synthesize','声音合成中… 第 1/10 段 · 已完成 0 段','生成配音 1/10'],['translate','正在翻译字幕 157 / 271…','翻译字幕 157/271']]){
       const after=await setStatus(...args);for(const key of ['bar','progress','stop'])assert.deepEqual(after[key],before[key],key+' must not move when stage text changes');assert.equal(await page.locator('.scene-stage').evaluate(el=>el.getBoundingClientRect().top),top);
     }
   };
