(async()=>{const options={headless:true};if(process.env.AUDIOCPP_BROWSER_EXECUTABLE)options.executablePath=process.env.AUDIOCPP_BROWSER_EXECUTABLE;const browser=await chromium.launch(options);let failures=0;const selected=cases.filter(([name])=>!process.env.AUDIOCPP_BROWSER_TEST_FILTER||name.includes(process.env.AUDIOCPP_BROWSER_TEST_FILTER));assert.ok(selected.length);for(const[name,run]of selected){const backend=fixture(),context=await browser.newContext({viewport:{width:1440,height:1000},serviceWorkers:'block'}),page=await context.newPage(),errors=[];page.setDefaultTimeout(12000);page.on('pageerror',e=>errors.push(e.message));await page.route('**/*',async route=>{try{await backend.route(route);}catch(e){backend.errors.push(e.stack);await route.abort();}});try{await run(page,backend);assert.deepEqual(errors,[]);assert.deepEqual(backend.errors,[]);console.log(`PASS ${name}`);}catch(e){failures++;console.error(`FAIL ${name}\n${e.stack}`);if(errors.length||backend.errors.length)console.error(JSON.stringify({errors,network:backend.errors}));if(process.env.AUDIOCPP_BROWSER_SCREENSHOTS){await fs.mkdir(process.env.AUDIOCPP_BROWSER_SCREENSHOTS,{recursive:true});await page.screenshot({path:path.join(process.env.AUDIOCPP_BROWSER_SCREENSHOTS,`scenario-failure-${failures}.png`),fullPage:true});}}finally{await context.close();}}await browser.close();console.log(`Scenario browser regression: ${selected.length-failures}/${selected.length} passed`);if(failures)process.exitCode=1;})().catch(e=>{console.error(e);process.exitCode=1;});
